document.querySelectorAll('.ux-app').forEach(app => { app.querySelectorAll('[data-go]').forEach(button => button.addEventListener('click', () => { const target = button.dataset.go; app.querySelectorAll('[data-view]').forEach(view => view.classList.toggle('active',view.dataset.view === target)); app.querySelectorAll('.ux-nav [data-go]').forEach(nav => { const section = ['adicionar','qr','convite','proximos','privacidade'].includes(target) ? 'conversas' : ['cidade','biblia','saude','cofre','preparar'].includes(target) ? 'mais' : target; const active = nav.dataset.go === section; nav.classList.toggle('active',active); nav.setAttribute('aria-pressed',String(active)); }); app.querySelector('.ux-content').scrollTop=0; })); });
document.querySelectorAll('.ux-app').forEach(app => { app.querySelectorAll('[data-context]').forEach(button => button.addEventListener('click', () => { app.querySelectorAll('[data-context]').forEach(tab => { const active=tab===button;tab.classList.toggle('active',active);tab.setAttribute('aria-pressed',String(active)); }); app.querySelectorAll('[data-pane]').forEach(pane=>pane.classList.toggle('active',pane.dataset.pane===button.dataset.context)); })); });
